from vuln_scanner.core import ScanEngine
from vuln_scanner.plugins.base import ScannerPlugin, Finding

# --- MOCK OBJECTS FOR TESTING ---

class MockFinding(Finding):
    """Concrete implementation of Finding for testing purposes."""
    def __init__(self, title: str, severity: str):
        self.title = title
        self.severity = severity
        self.plugin_id = "mock_plugin"

class MockPlugin(ScannerPlugin):
    """A controllable plugin to simulate various scan behaviors."""
    def __init__(self, config: Dict[str, Any]):
        self.plugin_id = config.get("id", "test_plugin")
        self.behavior = config.get("behavior", "success")
        self.delay = config.get("delay", 0)
        self.mock_findings = config.get("findings", [])

    async def run(self, target: str) -> List[Finding]:
        if self.delay > 0:
            await asyncio.sleep(self.delay)
        
        if self.behavior == "fail":
            raise RuntimeError("Simulated plugin failure")
        
        if self.behavior == "timeout":
            await asyncio.sleep(10) # Simulate long hang
            
        return self.mock_findings

# --- TEST SUITE ---

class TestScanEngine:
    
    @pytest.fixture
    def engine(self):
        """Provides a fresh ScanEngine instance for every test."""
        return ScanEngine(concurrency_limit=5)

    def test_register_plugin(self, engine):
        """Verify that plugins are correctly instantiated and registered."""
        config = {"id": "test_plugin_1"}
        engine.register_plugin(MockPlugin, config)
        
        assert len(engine.plugins) == 1
        assert engine.plugins[0].plugin_id == "test_plugin_1"
        assert isinstance(engine.plugins[0], MockPlugin)

    @pytest.mark.asyncio
    async def test_scan_success_aggregation(self, engine):
        """Verify that findings from multiple plugins are aggregated correctly."""
        # Setup plugins with specific findings
        findings_1 = [MockFinding("Vuln 1", "High"), MockFinding("Vuln 2", "Low")]
        findings_2 = [MockFinding("Vuln 3", "Medium")]
        
        engine.register_plugin(MockPlugin, {"id": "p1", "findings": findings_1})
        engine.register_plugin(MockPlugin, {"id": "p2", "findings": findings_2})
        
        await engine.scan("127.0.0.1")
        
        assert len(engine.results) == 3
        assert any(f.title == "Vuln 1" for f in engine.results)
        assert any(f.title == "Vuln 3" for f in engine.results)

    @pytest.mark.asyncio
    async def test_plugin_fault_isolation(self, engine):
        """Ensure a failing plugin does not stop other plugins from executing."""
        # Plugin 1 fails, Plugin 2 succeeds
        engine.register_plugin(MockPlugin, {"id": "fail_plugin", "behavior": "fail"})
        engine.register_plugin(MockPlugin, {"id": "success_plugin", "findings": [MockFinding("Safe", "Info")]})
        
        # This should not raise an exception
        await engine.scan("127.0.0.1")
        
        # Only the successful plugin's findings should be present
        assert len(engine.results) == 1
        assert engine.results[0].title == "Safe"

    @pytest.mark.asyncio
    async def test_concurrency_limit(self, engine):
        """
        Verify that the semaphore limits concurrent execution.
        We use a small concurrency limit and plugins with delays.
        """
        engine.semaphore = asyncio.Semaphore(2) # Strict limit of 2
        
        # Register 5 plugins that take some time to run
        for i in range(5):
            engine.register_plugin(MockPlugin, {"id": f"p{i}", "delay": 0.1})
        
        start_time = asyncio.get_event_loop().time()
        await engine.scan("127.0.0.1")
        end_time = asyncio.get_event_loop().time()
        
        # If concurrency is 2, 5 plugins with 0.1s delay should take ~0.3s (2+2+1)
        # If it were sequential, it would be 0.5s. If fully parallel, 0.1s.
        duration = end_time - start_time
        assert 0.2 <= duration <= 0.4

    @pytest.mark.asyncio
    async def test_empty_plugin_list(self, engine):
        """Verify engine behavior when no plugins are registered."""
        await engine.scan("127.0.0.1")
        assert engine.results == []

